<script setup>
import ProductImage from "../components/ProductImage.vue";
import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {sellers,products,money} from '../data/catalog';import {useCart} from '../composables/cart';const route=useRoute(),{add}=useCart();const seller=computed(()=>sellers.find(s=>s.id===route.params.seller));const query=ref(''),category=ref('All'),sort=ref('Featured');const catalog=computed(()=>products.filter(p=>p.seller===seller.value?.id));const categories=computed(()=>['All',...new Set(catalog.value.map(p=>p.category))]);const filtered=computed(()=>{let a=catalog.value.filter(p=>(category.value==='All'||p.category===category.value)&&p.name.toLowerCase().includes(query.value.toLowerCase()));return sort.value==='Price: low to high'?a.sort((a,b)=>a.price-b.price):sort.value==='Price: high to low'?a.sort((a,b)=>b.price-a.price):a});
</script>
<template><div class="shell py-7"><template v-if="seller"><div class="relative overflow-hidden rounded-[30px] bg-[#00532d] p-7 text-white md:p-12" data-aos="fade-up"><img :src="seller.coverImage" alt="" class="absolute inset-0 h-full w-full object-cover" @error="$event.target.style.display='none'"/><div class="absolute inset-0 bg-gradient-to-r from-[#003b20] via-[#00532d]/90 to-[#00532d]/40"></div><div class="relative max-w-2xl"><p class="mb-4 text-sm font-bold text-green-200"><i class="fa-solid fa-location-dot"></i> {{seller.location}} · {{seller.category}}</p><img :src="seller.logo" :alt="seller.name + ' logo'" class="mb-4 h-16 w-16 rounded-2xl border-2 border-white/70"/><h1 class="text-4xl font-black tracking-tight md:text-6xl">{{seller.name}}</h1><p class="mt-4 max-w-lg text-green-50">{{seller.description}}</p><div class="mt-6 flex flex-wrap gap-3 text-sm"><span class="rounded-full bg-white/15 px-4 py-2"><i class="fa-solid fa-star text-yellow-300"></i> {{seller.rating}}</span><span class="rounded-full bg-white/15 px-4 py-2">Open now · {{seller.eta}}</span><span class="rounded-full bg-white/15 px-4 py-2">Pickup available</span></div></div></div><div class="mt-6 flex flex-wrap gap-2 md:hidden"><router-link v-for="s in sellers" :key="s.id" class="secondary" :to="'/store/'+s.id">{{s.name}}</router-link></div><div class="mt-9 flex flex-wrap items-end justify-between gap-4"><div><p class="text-sm font-bold text-green-700">THE GOOD STUFF</p><h2 class="text-3xl font-black">Shop the store</h2></div><div class="flex flex-wrap gap-2"><label class="field flex w-auto items-center gap-2"><i class="fa-solid fa-magnifying-glass"></i><input v-model="query" placeholder="Search products" aria-label="Search products"/></label><select v-model="sort" class="field w-auto" aria-label="Sort products"><option>Featured</option><option>Price: low to high</option><option>Price: high to low</option></select></div></div><div class="my-6 flex flex-wrap gap-2"><button v-for="c in categories" :key="c" :class="category===c?'primary':'secondary'" @click="category=c">{{c}}</button></div><p class="mb-4 text-sm text-gray-500">{{filtered.length}} products</p><div class="grid grid-cols-2 gap-3 md:grid-cols-3 lg:grid-cols-4 md:gap-5"><article v-for="p in filtered" :key="p.id" class="panel !p-3 transition hover:-translate-y-1 hover:shadow-lg"><router-link :to="`/store/${seller.id}/product/${p.id}`"><div class="art group relative overflow-hidden"><ProductImage :src="p.image" :alt="p.name" :emoji="p.emoji"/><span v-if="p.old" class="absolute left-2 top-2 rounded-full bg-green-700 px-2 py-1 text-xs text-white">Offer</span></div><p class="mt-3 text-xs text-gray-500">{{p.category}}</p><h3 class="font-bold">{{p.name}}</h3></router-link><p class="my-2 font-black text-[#00532d]">{{money(p.price)}} <del v-if="p.old" class="text-xs font-normal text-gray-400">{{money(p.old)}}</del></p><router-link v-if="p.variants.length" class="secondary w-full" :to="`/store/${seller.id}/product/${p.id}`">Choose options</router-link><button v-else class="secondary w-full" :disabled="!p.stock" @click="add(p)"><i class="fa-solid fa-plus"></i>{{p.stock?'Add':'Sold out'}}</button></article></div><div v-if="!filtered.length" class="panel text-center">No products match. <button class="secondary" @click="query='';category='All'">Clear filters</button></div></template><div v-else class="panel">Store not found. <router-link to="/">Browse stores</router-link></div></div></template>
